<?php
require __DIR__.'/config/bootstrap.php';
$id=(int)($_GET['id']??0); $q=db()->prepare("SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.status='active'"); $q->execute([$id]); $p=$q->fetch(); if(!$p){http_response_code(404);exit('Product not found');}
$imgs=db()->prepare('SELECT image_path FROM product_images WHERE product_id=? ORDER BY sort_order');$imgs->execute([$id]);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=e($p['name'])?> | Royal Store</title><meta name="description" content="<?=e(substr(strip_tags($p['description']),0,155))?>"><link rel="stylesheet" href="/assets/css/store.css"></head><body><header class="top"><a class="brand" href="/">ROYAL</a><a href="/cart.php">Cart</a></header><main class="detail"><div><?php foreach($imgs as $im):?><img class="detailimg" src="/<?=e($im['image_path'])?>" alt="<?=e($p['name'])?>"><?php endforeach;?></div><div><small><?=e($p['category']??'Product')?> · SKU <?=e($p['sku'])?></small><h1><?=e($p['name'])?></h1><p><?=nl2br(e($p['description']))?></p><h2><?=money($p['sale_price'] ?: $p['price'])?></h2><p><?=((int)$p['stock']>0?'In stock':'Out of stock')?></p><form method="post" action="/cart.php"><?=Security::field()?><input type="hidden" name="product_id" value="<?=$id?>"><input type="number" name="qty" min="1" max="<?=max(1,(int)$p['stock'])?>" value="1"><button <?=((int)$p['stock']<1?'disabled':'')?>>Add to cart</button></form></div></main></body></html>
